-- Isolated catalogue_fixture database only. Contains catalogue data, never users, orders or credentials.
-- Load before tests/catalog-packaging.php and tests/catalog-publication.php. Never run against a live database.
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` int NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `category_id` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `price` int NOT NULL,
  `old_price` int DEFAULT NULL,
  `image` varchar(500) COLLATE utf8mb4_general_ci NOT NULL,
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `badge` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `weight` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `description` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `short_description` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ingredients` longtext COLLATE utf8mb4_general_ci,
  `features` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `wb_link` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ozon_link` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_active` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `h1` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `seo_title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `seo_description` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `image_alt` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sku` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `gtin` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `availability` varchar(50) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'in_stock',
  `published_at` datetime DEFAULT NULL,
  `usage_text` longtext COLLATE utf8mb4_general_ci,
  `contraindications` longtext COLLATE utf8mb4_general_ci,
  `country` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `shelf_life` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `storage_conditions` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bad_disclaimer` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `active_components_text` longtext COLLATE utf8mb4_general_ci,
  `legal_status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'unknown',
  `official_purpose` longtext COLLATE utf8mb4_general_ci,
  `regulatory_evidence` longtext COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_products_slug` (`slug`),
  KEY `idx_products_category_id` (`category_id`),
  KEY `idx_products_is_active` (`is_active`),
  KEY `idx_products_availability` (`availability`),
  KEY `idx_products_published_at` (`published_at`),
  CONSTRAINT `products_chk_1` CHECK (json_valid(`images`)),
  CONSTRAINT `products_chk_2` CHECK (json_valid(`features`))
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `product_groups`;
CREATE TABLE `product_groups` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `product_group_items`;
CREATE TABLE `product_group_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `group_id` int NOT NULL,
  `product_id` int NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_product_group_items_product` (`product_id`),
  UNIQUE KEY `uniq_product_group_items_group_product` (`group_id`,`product_id`),
  KEY `idx_product_group_items_group_id` (`group_id`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `product_images`;
CREATE TABLE `product_images` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL,
  `path` varchar(500) COLLATE utf8mb4_general_ci NOT NULL,
  `alt` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_main` tinyint NOT NULL DEFAULT '0',
  `width` int DEFAULT NULL,
  `height` int DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `mime_type` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `size` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_product_images_product_id` (`product_id`),
  KEY `idx_product_images_is_main` (`is_main`),
  KEY `idx_product_images_sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=275 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `product_attribute_values`;
CREATE TABLE `product_attribute_values` (
  `id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL,
  `attribute_value_id` int NOT NULL,
  `value_text` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_product_attribute_values_product_value` (`product_id`,`attribute_value_id`),
  KEY `idx_product_attribute_values_product_id` (`product_id`),
  KEY `idx_product_attribute_values_value_id` (`attribute_value_id`)
) ENGINE=InnoDB AUTO_INCREMENT=407 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `product_blog_posts`;
CREATE TABLE `product_blog_posts` (
  `product_id` int NOT NULL,
  `blog_post_id` int NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  UNIQUE KEY `uniq_product_blog_posts_product_post` (`product_id`,`blog_post_id`),
  KEY `idx_product_blog_posts_product` (`product_id`),
  KEY `idx_product_blog_posts_post` (`blog_post_id`),
  KEY `idx_product_blog_posts_sort_order` (`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `material_placements`;
CREATE TABLE `material_placements` (
  `kind` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `material_id` int NOT NULL,
  `target_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `target_id` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`kind`,`material_id`,`target_type`,`target_id`),
  KEY `idx_material_target` (`kind`,`target_type`,`target_id`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `faq_items`;
CREATE TABLE `faq_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `question` varchar(500) COLLATE utf8mb4_general_ci NOT NULL,
  `answer` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `page_scope` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `page_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_active` tinyint NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `category_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_faq_items_scope` (`page_scope`,`page_id`),
  KEY `idx_faq_items_active` (`is_active`),
  KEY `idx_faq_items_sort_order` (`sort_order`),
  KEY `idx_faq_items_category` (`category_id`),
  CONSTRAINT `fk_faq_items_category` FOREIGN KEY (`category_id`) REFERENCES `material_categories` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` int NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `parent_id` int DEFAULT NULL,
  `h1` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `seo_title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `seo_description` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `intro_text` longtext COLLATE utf8mb4_general_ci,
  `bottom_text` longtext COLLATE utf8mb4_general_ci,
  `image` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_indexable` tinyint NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_categories_slug` (`slug`),
  KEY `idx_categories_parent_id` (`parent_id`),
  KEY `idx_categories_is_indexable` (`is_indexable`),
  KEY `idx_categories_sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `attributes`;
CREATE TABLE `attributes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `filter_prefix` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_filterable` tinyint NOT NULL DEFAULT '1',
  `is_indexable` tinyint NOT NULL DEFAULT '1',
  `show_on_product` tinyint NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_attributes_slug` (`slug`),
  UNIQUE KEY `uniq_attributes_filter_prefix` (`filter_prefix`),
  KEY `idx_attributes_filterable` (`is_filterable`),
  KEY `idx_attributes_sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `attribute_values`;
CREATE TABLE `attribute_values` (
  `id` int NOT NULL AUTO_INCREMENT,
  `attribute_id` int NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `h1` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `seo_title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `seo_description` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `intro_text` longtext COLLATE utf8mb4_general_ci,
  `bottom_text` longtext COLLATE utf8mb4_general_ci,
  `short_description` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `synonyms` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `is_indexable` tinyint NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_attribute_values_attribute_slug` (`attribute_id`,`slug`),
  KEY `idx_attribute_values_attribute_id` (`attribute_id`),
  KEY `idx_attribute_values_slug` (`slug`),
  KEY `idx_attribute_values_sort_order` (`sort_order`),
  CONSTRAINT `attribute_values_chk_1` CHECK (json_valid(`synonyms`))
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS `material_target_selections`;
CREATE TABLE `material_target_selections` (
  `kind` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `target_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `target_id` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`kind`,`target_type`,`target_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
DROP TABLE IF EXISTS program_locks;
CREATE TABLE IF NOT EXISTS program_locks (id VARCHAR(255) PRIMARY KEY,payload LONGTEXT);
CREATE TABLE IF NOT EXISTS blog_posts (id INT PRIMARY KEY,deleted_at DATETIME NULL);
CREATE TABLE IF NOT EXISTS certificates (id INT PRIMARY KEY);
SET FOREIGN_KEY_CHECKS=1;